<?php declare(strict_types=1);
function uC(PDO $db,string $sql):int{try{return(int)$db->query($sql)->fetchColumn();}catch(Throwable){return 0;}}
$users=[];try{$users=$db->query('SELECT id,name,email,role,credits,daily_credits,plan,created_at FROM creator_users ORDER BY id DESC LIMIT 300')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
$total=uC($db,'SELECT COUNT(*) FROM creator_users');$admins=uC($db,"SELECT COUNT(*) FROM creator_users WHERE role IN ('admin','superadmin')");$credits=uC($db,'SELECT COALESCE(SUM(credits),0) FROM creator_users');$activePlan=uC($db,"SELECT COUNT(*) FROM creator_users WHERE plan IS NOT NULL AND plan<>''");
?>
<div class="av4-page"><div class="av4-stat-grid"><div class="av4-stat"><b><?=number_format($total)?></b><span>Total users</span></div><div class="av4-stat purple"><b><?=number_format($admins)?></b><span>Admins / superadmins</span></div><div class="av4-stat blue"><b><?=number_format($credits)?></b><span>Credits held</span></div><div class="av4-stat green"><b><?=number_format($activePlan)?></b><span>Users with plan</span></div></div>
<div class="av4-card"><div class="av4-head"><div><h2>👥 User & Credit Management</h2><p>Search users, inspect balances and change role or credits safely.</p></div><input id="av4UserSearch" class="av4-search" placeholder="Search name, email, ID, role…"></div><div class="av4-table"><table id="av4UserTable"><thead><tr><th>ID</th><th>User</th><th>Email</th><th>Role</th><th>Credits</th><th>Daily credits</th><th>Plan</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $r):?><tr><td><?=av4h($r['id'])?></td><td><b><?=av4h($r['name'])?></b></td><td><?=av4h($r['email'])?></td><td><span class="av4-tag <?=in_array($r['role'],['admin','superadmin'],true)?'purple':'gray'?>"><?=av4h($r['role'])?></span></td><td><?=number_format((int)$r['credits'])?></td><td><?=number_format((int)$r['daily_credits'])?></td><td><?=av4h($r['plan']??'—')?></td><td><?=av4h($r['created_at']??'')?></td><td><details><summary class="av4-summary">Edit</summary><form class="av4-mini-form" method="post" action="/smart-toolz/admin/admin-actions.php"><input type="hidden" name="back" value="users"><input type="hidden" name="csrf_token" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="<?=av4h($r['id'])?>"><input type="hidden" name="action" value="user_role"><select name="role"><option value="user" <?=$r['role']==='user'?'selected':''?>>user</option><option value="admin" <?=$r['role']==='admin'?'selected':''?>>admin</option><option value="superadmin" <?=$r['role']==='superadmin'?'selected':''?>>superadmin</option></select><button class="av4-btn small">Role</button></form><form class="av4-mini-form" method="post" action="/smart-toolz/admin/admin-actions.php"><input type="hidden" name="back" value="users"><input type="hidden" name="csrf_token" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="<?=av4h($r['id'])?>"><input type="hidden" name="action" value="user_credits"><input name="credits" type="number" min="0" value="<?=av4h($r['credits'])?>"><input name="daily_credits" type="number" min="0" value="<?=av4h($r['daily_credits'])?>"><button class="av4-btn primary small">Save credits</button></form></details></td></tr><?php endforeach;if(!$users):?><tr><td colspan="9" class="empty">No users found.</td></tr><?php endif;?></tbody></table></div></div></div>
<script>(function(){const i=document.getElementById('av4UserSearch'),t=document.getElementById('av4UserTable');if(i&&t)i.addEventListener('input',()=>{const s=i.value.toLowerCase();t.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(s)?'':'none')});})();</script>
